// unified card anatomy used sitewide (websites, scripts, summaries)
function cardShell(title, badge, bodyHTML, footerHTML){
  return `<div class="card">
    <div class="card-h">${title}${badge||''}</div>
    <div class="card-b">${bodyHTML}</div>
    <div class="card-f">${footerHTML}</div>
  </div>`;
}
// reverse index: image -> websites that appear in it
const img2sites = {};
websites.forEach(w => w.src.forEach(s => {
  (s.match(/IMG_\d+/g)||[]).forEach(m =>
    (img2sites[m] = img2sites[m] || []).push({label: w.name, url: w.url}));
}));
